package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Explicit opt-in, fake deferred delivery, verified receipts, retry and Off. No provider/OS jobs. */
public final class AutoCloudBackupFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);final List<Activity> activities=new CopyOnWriteArrayList<>();volatile Activity current;AutoCloudBackupFixture f;
 interface Work{void run()throws Exception;}interface Ready{boolean yes()throws Exception;}
 void await(Ready condition)throws Exception{long until=SystemClock.elapsedRealtime()+10000;while(!condition.yes()){if(SystemClock.elapsedRealtime()>until)throw new AssertionError("Expected automatic backup state");Thread.sleep(25);}}
 final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue(a instanceof CloudBackupActivity);activities.add(a);}public void onActivityResumed(Activity a){current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
 View root(){for(View v:WindowInspector.getGlobalWindowViews())if(v.isAttachedToWindow()&&v.hasWindowFocus()&&v.getContext().getPackageName().equals(c.getPackageName()))return v;return null;}
 View find(View v,String text,boolean switches){if(v==null)return null;if((!switches||v instanceof Switch)&&(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&text.contentEquals(((TextView)v).getText())))return v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){View found=find(((ViewGroup)v).getChildAt(n),text,switches);if(found!=null)return found;}return null;}
 Rect bounds(String text,boolean switches){Rect[] r={null};i.runOnMainSync(()->{View v=find(root(),text,switches);while(v!=null&&!v.isClickable())v=v.getParent() instanceof View?(View)v.getParent():null;if(v==null||!v.isEnabled())return;Rect a=new Rect();if(v.getGlobalVisibleRect(a)&&a.height()==v.getHeight()&&a.width()==v.getWidth()&&v.getHeight()>=Design.dp(c,48)){int[] screen=new int[2];v.getLocationOnScreen(screen);r[0]=new Rect(screen[0],screen[1],screen[0]+v.getWidth(),screen[1]+v.getHeight());}else v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),false);});return r[0];}
 void click(String text,boolean switches)throws Exception{await(()->bounds(text,switches)!=null);frame();Rect r=bounds(text,switches);assertNotNull(r);assertTrue(d.click(r.centerX(),r.centerY()));}
 void frame()throws Exception{CountDownLatch committed=new CountDownLatch(1);i.runOnMainSync(()->{View v=root();assertNotNull(v);v.getViewTreeObserver().registerFrameCommitCallback(committed::countDown);v.invalidate();});assertTrue(committed.await(5,TimeUnit.SECONDS));}
 void ready()throws Exception{AutoCloudBackups.drain(10000);await(()->{boolean[] ok={false};i.runOnMainSync(()->ok[0]=current instanceof CloudBackupActivity&&current.hasWindowFocus()&&((CloudBackupActivity)current).getWindow().getDecorView().isAttachedToWindow());return ok[0];});await(()->{boolean[] yes={false};i.runOnMainSync(()->yes[0]=find(root(),"Automatic metadata backup",true)!=null&&find(root(),AutoCloudBackups.state.message,false)!=null);return yes[0];});}
 void capture(String name)throws Exception{ready();await(()->bounds("Automatic metadata backup",true)!=null);frame();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"automatic-backup-"+name+".png")));}
 void launch()throws Exception{current=i.startActivitySync(new Intent(c,CloudBackupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK).putExtra("visualReview",true).putExtra("verificationLabel","TEST FIXTURE · private records, fake folder/jobs"));ready();}
 void run(Work work)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());AutoCloudBackups.State oldState=AutoCloudBackups.state;Records.Factory oldRecords=Records.factory;AutoCloudBackups.Factory oldFactory=AutoCloudBackups.factory;AutoCloudBackups.Environments oldEnvironment=AutoCloudBackups.environments;CloudBackupSettings.Factory oldSettings=CloudBackupSettings.factory;CloudBackupJobs.Factory oldManual=CloudBackupJobs.factory;Application app=(Application)c.getApplicationContext();try(AutoCloudBackupFixture fixture=new AutoCloudBackupFixture()){f=fixture;try{AutoCloudBackups.drain(10000);Records.factory=f.records;AutoCloudBackups.factory=context->new AutoCloudBackupStore(context,f.journal);AutoCloudBackups.environments=(context,records)->f.env;CloudBackupSettings.factory=context->f.prefs;CloudBackupJobs.factory=(context,records)->new CloudBackupJob.Work(){public CloudBackupCopy.Receipt save(java.util.function.BooleanSupplier active){throw new AssertionError("No manual export from this fixture");}public void cancel(){}};app.registerActivityLifecycleCallbacks(lifecycle);work.run();}catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");folder.mkdirs();d.takeScreenshot(new File(folder,"automatic-backup-failure.png"));d.dumpWindowHierarchy(new File(folder,"automatic-backup-failure.xml"));}catch(Exception capture){failure.addSuppressed(capture);}throw failure;}finally{i.runOnMainSync(()->{for(Activity a:activities)if(!a.isDestroyed())a.finish();});await(()->activities.stream().allMatch(Activity::isDestroyed));AutoCloudBackups.drain(10000);CloudBackupJobs.drain(f.records,10000);for(Activity a:activities)assertTrue(((CloudBackupActivity)a).awaitLocal(10000));CloudBackupJobs.forget(f.records);app.unregisterActivityLifecycleCallbacks(lifecycle);Records.factory=oldRecords;AutoCloudBackups.factory=oldFactory;AutoCloudBackups.environments=oldEnvironment;CloudBackupSettings.factory=oldSettings;CloudBackupJobs.factory=oldManual;AutoCloudBackups.state=oldState;}}}
 @Test public void explicitOptionRecreatesAndSavedNightHasOneVerifiedVersionAfterReopen()throws Exception{run(()->{launch();capture("off");assertFalse(f.store.owner().enabled);assertEquals(0,f.env.creates);click("Automatic metadata backup",true);await(()->f.store.owner().enabled&&!AutoCloudBackups.state.busy);capture("enabled");Activity old=current;i.runOnMainSync(old::recreate);await(()->current!=old&&current.hasWindowFocus());capture("recreated");assertTrue(f.store.owner().enabled);assertEquals(0,f.env.creates);f.queue();AutoCloudBackups.inspect(c);await(()->AutoCloudBackups.state.pending==1);capture("queued");String token=f.store.owner().token;CountDownLatch finished=new CountDownLatch(1);AutoCloudBackups.run(c,token,new java.util.concurrent.atomic.AtomicBoolean(),finished::countDown);assertTrue(finished.await(10,TimeUnit.SECONDS));await(()->AutoCloudBackups.state.verified==1);capture("verified");assertEquals(1,f.env.creates);assertTrue(CloudBackupSettings.history(f.prefs).get(0).verified);Activity before=current;i.runOnMainSync(before::finish);await(before::isDestroyed);launch();assertTrue(f.store.owner().enabled);assertEquals(1,f.env.creates);f.queue();f.deliver();assertEquals(1,f.env.creates);});}
 @Test public void uncertainWriteRequiresOwnedConfirmationThenOffCancelsFutureDelivery()throws Exception{run(()->{
  f.enable();f.queue();f.env.corrupt=true;f.deliver();
  assertEquals("UNCERTAIN",f.task().state);launch();capture("uncertain");
  click("Retry automatic backup",false);click("Cancel",false);
  assertEquals("Cancel must preserve the uncertain request", "UNCERTAIN",f.task().state);
  click("Retry automatic backup",false);f.env.corrupt=false;click("Retry",false);
  await(()->f.task().state.equals("PENDING"));
  CountDownLatch done=new CountDownLatch(1);
  AutoCloudBackups.run(c,f.store.owner().token,new java.util.concurrent.atomic.AtomicBoolean(),done::countDown);
  assertTrue(done.await(10,TimeUnit.SECONDS));await(()->AutoCloudBackups.state.verified==1);
  capture("retried");assertEquals(2,f.env.creates);
  click("Automatic metadata backup",true);await(()->!f.store.owner().enabled&&!AutoCloudBackups.state.busy);
  capture("disabled");assertEquals(2,f.env.documents.size());assertEquals("",f.env.scheduled);
 });}
}
